// jab/get-categories — Get Categories
/** Retrieves all categories as a flat list of term objects. */
export interface GetCategoriesInput {
  /**
   * Exclude terms with no published posts.
   */
  hide_empty?: boolean;
  /**
   * Maximum number of terms to return.
   */
  number?: number;
}

export interface GetCategoriesOutput {
  categories: {
    id: number;
    name: string;
    slug: string;
    description: string;
    count: number;
    /**
     * 0 for top-level terms; parent term_id otherwise.
     */
    parent_id: number;
  }[];
}

