// jab/get-menus — Get Nav Menus
/** Returns every registered WordPress nav menu with its items as a flat list and the theme locations each menu is assigned to. Items carry parent_id so consumers can rebuild the tree client-side. */
export interface GetMenusInput {}

export interface GetMenusOutput {
  menus: {
    id: number;
    slug: string;
    name: string;
    /**
     * Theme-registered menu locations (e.g. "primary", "footer") this menu is assigned to.
     */
    locations: string[];
    /**
     * Flat list of menu items. Use parent_id to reconstruct the tree.
     */
    items: {
      id: number;
      title: string;
      url: string;
      /**
       * Link target. Empty string for same-window, "_blank" for new window.
       */
      target: string;
      /**
       * WP object kind: "post", "page", "category", "custom", etc.
       */
      object_type: string;
      /**
       * ID of the linked WP object, when applicable. 0 for custom URLs.
       */
      object_id: number;
      /**
       * ID of the parent menu item. 0 for top-level items.
       */
      parent_id: number;
      /**
       * Item order within its parent.
       */
      order: number;
    }[];
  }[];
}

